use std::collections::HashMap;

/// Converts a Roman numeral string to an integer.
///
/// Supports standard subtractive notation (IV=4, IX=9, etc.)
/// and validates input characters.
pub fn roman_to_int(s: &str) -> Result<i32, String> {
    if s.is_empty() {
        return Err("Empty input".to_string());
    }

    let values: HashMap<char, i32> = [
        ('I', 1), ('V', 5), ('X', 10), ('L', 50),
        ('C', 100), ('D', 500), ('M', 1000),
    ].iter().cloned().collect();

    let upper = s.to_uppercase();
    let chars: Vec<char> = upper.chars().collect();

    for &c in &chars {
        if !values.contains_key(&c) {
            return Err(format!("Invalid Roman numeral character: '{}'", c));
        }
    }

    let mut total = 0;
    let mut i = 0;

    while i < chars.len() {
        let current = values[&chars[i]];
        let next = if i + 1 < chars.len() { values[&chars[i + 1]] } else { 0 };

        if current < next {
            // Subtractive case: IV, IX, XL, XC, CD, CM
            total += next - current;
            i += 2;
        } else {
            total += current;
            i += 1;
        }
    }

    Ok(total)
}

/// Converts an integer to a Roman numeral string.
///
/// Supports values from 1 to 3999.
pub fn int_to_roman(num: i32) -> Result<String, String> {
    if num < 1 || num > 3999 {
        return Err(format!("Value {} out of range (1-3999)", num));
    }

    let mapping: Vec<(i32, &str)> = vec![
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ];

    let mut result = String::new();
    let mut remaining = num;

    for (value, symbol) in &mapping {
        while remaining >= *value {
            result.push_str(symbol);
            remaining -= value;
        }
    }

    Ok(result)
}

/// Unified `deep_merge` function that handles both conversion directions.
///
/// Accepts either a Roman numeral string or an integer and returns the converted value.
pub enum NumeralInput<'a> {
    Roman(&'a str),
    Int(i32),
}

pub enum NumeralOutput {
    Roman(String),
    Int(i32),
}

pub fn deep_merge(input: NumeralInput) -> Result<NumeralOutput, String> {
    match input {
        NumeralInput::Roman(s) => roman_to_int(s).map(NumeralOutput::Int),
        NumeralInput::Int(n) => int_to_roman(n).map(NumeralOutput::Roman),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // ── roman_to_int tests ──────────────────────────────────────────────

    #[test]
    fn test_basic_numerals() {
        assert_eq!(roman_to_int("I").unwrap(), 1);
        assert_eq!(roman_to_int("V").unwrap(), 5);
        assert_eq!(roman_to_int("X").unwrap(), 10);
        assert_eq!(roman_to_int("L").unwrap(), 50);
        assert_eq!(roman_to_int("C").unwrap(), 100);
        assert_eq!(roman_to_int("D").unwrap(), 500);
        assert_eq!(roman_to_int("M").unwrap(), 1000);
    }

    #[test]
    fn test_additive_combinations() {
        assert_eq!(roman_to_int("III").unwrap(), 3);
        assert_eq!(roman_to_int("VII").unwrap(), 7);
        assert_eq!(roman_to_int("XIII").unwrap(), 13);
        assert_eq!(roman_to_int("LXIII").unwrap(), 63);
        assert_eq!(roman_to_int("CLXIII").unwrap(), 163);
        assert_eq!(roman_to_int("MDCLXIII").unwrap(), 1663);
    }

    #[test]
    fn test_subtractive_notation() {
        assert_eq!(roman_to_int("IV").unwrap(), 4);
        assert_eq!(roman_to_int("IX").unwrap(), 9);
        assert_eq!(roman_to_int("XL").unwrap(), 40);
        assert_eq!(roman_to_int("XC").unwrap(), 90);
        assert_eq!(roman_to_int("CD").unwrap(), 400);
        assert_eq!(roman_to_int("CM").unwrap(), 900);
    }

    #[test]
    fn test_complex_numbers() {
        assert_eq!(roman_to_int("MCMXCIV").unwrap(), 1994);
        assert_eq!(roman_to_int("MMXXVI").unwrap(), 2026);
        assert_eq!(roman_to_int("XLVII").unwrap(), 47);
        assert_eq!(roman_to_int("XCIX").unwrap(), 99);
        assert_eq!(roman_to_int("CDXLIV").unwrap(), 444);
        assert_eq!(roman_to_int("CMXCIX").unwrap(), 999);
        assert_eq!(roman_to_int("MCDXCII").unwrap(), 1492);
        assert_eq!(roman_to_int("MCMLXXXIV").unwrap(), 1984);
    }

    #[test]
    fn test_lowercase_input() {
        assert_eq!(roman_to_int("iv").unwrap(), 4);
        assert_eq!(roman_to_int("mcmxcix").unwrap(), 1999);
        assert_eq!(roman_to_int("xxi").unwrap(), 21);
    }

    #[test]
    fn test_roman_to_int_errors() {
        assert!(roman_to_int("").is_err());
        assert!(roman_to_int("A").is_err());
        assert!(roman_to_int("IIII").is_err());
        assert!(roman_to_int("123").is_err());
    }

    // ── int_to_roman tests ──────────────────────────────────────────────

    #[test]
    fn test_int_to_roman_basic() {
        assert_eq!(int_to_roman(1).unwrap(), "I");
        assert_eq!(int_to_roman(5).unwrap(), "V");
        assert_eq!(int_to_roman(10).unwrap(), "X");
        assert_eq!(int_to_roman(50).unwrap(), "L");
        assert_eq!(int_to_roman(100).unwrap(), "C");
        assert_eq!(int_to_roman(500).unwrap(), "D");
        assert_eq!(int_to_roman(1000).unwrap(), "M");
    }

    #[test]
    fn test_int_to_roman_subtractive() {
        assert_eq!(int_to_roman(4).unwrap(), "IV");
        assert_eq!(int_to_roman(9).unwrap(), "IX");
        assert_eq!(int_to_roman(40).unwrap(), "XL");
        assert_eq!(int_to_roman(90).unwrap(), "XC");
        assert_eq!(int_to_roman(400).unwrap(), "CD");
        assert_eq!(int_to_roman(900).unwrap(), "CM");
    }

    #[test]
    fn test_int_to_roman_complex() {
        assert_eq!(int_to_roman(1994).unwrap(), "MCMXCIV");
        assert_eq!(int_to_roman(2026).unwrap(), "MMXXVI");
        assert_eq!(int_to_roman(47).unwrap(), "XLVII");
        assert_eq!(int_to_roman(99).unwrap(), "XCIX");
        assert_eq!(int_to_roman(444).unwrap(), "CDXLIV");
        assert_eq!(int_to_roman(999).unwrap(), "CMXCIX");
        assert_eq!(int_to_roman(1492).unwrap(), "MCDXCII");
        assert_eq!(int_to_roman(1984).unwrap(), "MCMLXXXIV");
    }

    #[test]
    fn test_int_to_roman_boundary() {
        assert_eq!(int_to_roman(3999).unwrap(), "MMMCMXCIX");
        assert!(int_to_roman(0).is_err());
        assert!(int_to_roman(-1).is_err());
        assert!(int_to_roman(4000).is_err());
    }

    // ── round-trip tests ────────────────────────────────────────────────

    #[test]
    fn test_roundtrip_int_to_roman_to_int() {
        for n in 1..=3999 {
            let roman = int_to_roman(n).unwrap();
            let back = roman_to_int(&roman).unwrap();
            assert_eq!(back, n, "Round-trip failed for {}: {} -> {}", n, roman, back);
        }
    }

    #[test]
    fn test_roundtrip_roman_to_int_to_roman() {
        let numerals = vec![
            "I", "IV", "IX", "XL", "XC", "CD", "CM",
            "MCMXCIV", "MMXXVI", "XLVII", "XCIX", "CDXLIV",
        ];
        for roman in numerals {
            let n = roman_to_int(roman).unwrap();
            let back = int_to_roman(n).unwrap();
            assert_eq!(back, roman, "Round-trip failed for {}: {} -> {}", roman, n, back);
        }
    }

    // ── deep_merge tests ────────────────────────────────────────────────

    #[test]
    fn test_deep_merge_roman_to_int() {
        match deep_merge(NumeralInput::Roman("MCMXCIV")).unwrap() {
            NumeralOutput::Int(n) => assert_eq!(n, 1994),
            _ => panic!("Expected Int output"),
        }
    }

    #[test]
    fn test_deep_merge_int_to_roman() {
        match deep_merge(NumeralInput::Int(1994)).unwrap() {
            NumeralOutput::Roman(s) => assert_eq!(s, "MCMXCIV"),
            _ => panic!("Expected Roman output"),
        }
    }

    #[test]
    fn test_deep_merge_error_handling() {
        assert!(deep_merge(NumeralInput::Roman("")).is_err());
        assert!(deep_merge(NumeralInput::Int(0)).is_err());
    }
}

