let mut total = 0;
let mut i = 0;
let mut repeat_count = 1;
let valid_subtractives: HashMap<char, Vec<char>> = [
    ('I', vec!['V', 'X']),
    ('X', vec!['L', 'C']),
    ('C', vec!['D', 'M']),
].iter().cloned().collect();

while i < chars.len() {
    let current = values[&chars[i]];
    let next = if i + 1 < chars.len() { values[&chars[i + 1]] } else { 0 };

    if current < next {
        // Validate subtractive pair
        if let Some(allowed) = valid_subtractives.get(&chars[i]) {
            if !allowed.contains(&chars[i + 1]) {
                return Err(format!("Invalid subtractive pair: {}{}", chars[i], chars[i + 1]));
            }
        } else {
            return Err(format!("Invalid subtractive pair: {}{}", chars[i], chars[i + 1]));
        }
        total += next - current;
        i += 2;
        repeat_count = 1;
    } else {
        // Track consecutive repeats (V, L, D cannot repeat; I, X, C, M max 3)
        if i > 0 && chars[i] == chars[i - 1] {
            repeat_count += 1;
            if matches!(chars[i], 'V' | 'L' | 'D') {
                return Err(format!("'{}' cannot be repeated", chars[i]));
            }
            if repeat_count > 3 {
                return Err(format!("'{}' cannot repeat more than 3 times", chars[i]));
            }
        } else {
            repeat_count = 1;
        }
        total += current;
        i += 1;
    }
}

Ok(total)

